package logger

import (
	"log/slog"
	"time"

	"github.com/gofiber/fiber/v2"
)

// NewFiberMiddleware returns a Fiber middleware that logs HTTP requests using slog.
func NewFiberMiddleware() fiber.Handler {
	return func(c *fiber.Ctx) error {
		start := time.Now()
		path := c.Path()

		// Execute downstream handlers
		err := c.Next()

		latency := time.Since(start)
		status := c.Response().StatusCode()

		// Get request ID generated by Fiber requestid middleware
		reqID, _ := c.Locals("requestid").(string)
		if reqID == "" {
			reqID = c.Get(fiber.HeaderXRequestID)
		}

		// Use route path (e.g. /api/v1/parties/:id) if available to avoid unbounded cardinality
		route := c.Route().Path
		if route == "" {
			route = path
		}

		attrs := []slog.Attr{
			slog.String("request_id", reqID),
			slog.String("method", c.Method()),
			slog.String("path", path),
			slog.String("route", route),
			slog.Int("status", status),
			slog.Float64("latency_ms", float64(latency.Microseconds())/1000.0),
			slog.String("ip", c.IP()),
			slog.String("user_agent", c.Get(fiber.HeaderUserAgent)),
			slog.Int("bytes_sent", len(c.Response().Body())),
		}

		if err != nil {
			attrs = append(attrs, slog.String("error", err.Error()))
		}

		// Quiet logging for high-frequency healthchecks and metrics scrape endpoints
		if path == "/health" || path == "/metrics" {
			L().LogAttrs(c.Context(), slog.LevelDebug, "http health/metrics scrape", attrs...)
			return err
		}

		// Classify log level based on HTTP response status code
		var lvl slog.Level
		switch {
		case status >= 500:
			lvl = slog.LevelError
		case status >= 400:
			lvl = slog.LevelWarn
		default:
			lvl = slog.LevelInfo
		}

		L().LogAttrs(c.Context(), lvl, "http request completed", attrs...)
		return err
	}
}
